def bubble_sort(arr):
    n = len(arr)

    # 交换数组中的相邻元素
    for i in range(n-1):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]

